def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_d = sum(1 for _, o in history if o == 'D')
    my_d = sum(1 for m, _ in history if m == 'D')
    last_m, last_o = history[-1]

    # Endgame: against a nearly pure cooperator, defect in the last rounds.
    if n >= 97:
        if opp_d <= 3:
            return 'D'
        if opp_d <= 8 and last_o == 'C':
            return 'D'

    # If opponent just cooperated, cooperate (also recovers from their initial
    # defections quickly, matching one_D_TFT and four_D_ALLC behavior).
    if last_o == 'C':
        # Occasional probe against an extremely clean cooperator.
        if opp_d == 0 and 5 < n < 95 and n % 29 == 0:
            return 'D'
        return 'C'

    # Opponent defected last round.
    # Early game: retaliate once, then resume cooperation if they do.
    if n < 10:
        return 'D'
    if n < 25:
        if opp_d <= max(1, n // 8):
            return 'C'
        return 'D'

    # Opponent is a sustained defector: punish hard.
    if opp_d > n - opp_d:
        # Break DD lock if opponent recently showed any cooperation.
        recent_c = 0
        start = n - 6 if n >= 6 else 0
        for i in range(start, n):
            if history[i][1] == 'C':
                recent_c += 1
        if recent_c >= 1 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Mostly cooperative opponent who just defected: forgive quickly.
    if opp_d * 8 <= n:
        if n >= 3 and history[-2][1] == 'C':
            return 'D'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Moderate defector: tit-for-tat with mild forgiveness.
    # Break DD cycles since we both defecting yields only 1.
    if last_m == 'D' and n >= 2 and history[-2][1] == 'D':
        if opp_d * 4 <= n:
            return 'C'
    if opp_d * 3 > n:
        return 'D'
    if rng.random() < 0.35:
        return 'C'
    return 'D'
